/// <summary>
/// update field values to record after mapping to the entity.
/// </summary>
/// <param name="_sender"><c>InventInventoryMovementJournalEntryV4Entity</c> raising the event.</param>
/// <param name="_eventArgs">The arguments of this event.</param>
[DataEventHandler(tableStr(InventInventoryMovementJournalEntryV4Entity), DataEventType::MappedEntityToDataSource)]
public static void InventInventoryMovementJournalEntryV4Entity_onMappedEntityToDataSource(Common _sender, DataEventArgs _eventArgs)
{
    DataEntityContextEventArgs contextEventArgs = _eventArgs as DataEntityContextEventArgs;
    DataEntityRuntimeContext entityCtx = contextEventArgs.parmEntityContext();
    DataEntityDataSourceRuntimeContext dataSourceCtx = contextEventArgs.parmEntityDataSourceContext();

    if ((entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert || entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Update)
        && dataSourceCtx.name() == dataEntityDataSourceStr(InventInventoryMovementJournalEntryV4Entity, InventJournalTrans))
    {
        InventInventoryMovementJournalEntryV4Entity inventInventoryMovementJournalEntry = _sender as InventInventoryMovementJournalEntryV4Entity;
        InventJournalTrans inventJournalTrans = dataSourceCtx.getBuffer();

        if (InventJournalName::find(inventInventoryMovementJournalEntry.JournalNameId).METExternalWMSUOM && InventJournalTable::find(inventInventoryMovementJournalEntry.JournalNumber).METJournalLinesCount)
        {
            if (inventInventoryMovementJournalEntry.CatchWeightQuantity)
            {
                inventInventoryMovementJournalEntry.CatchWeightQuantity = METJournalUnitConversion::construct().getConvertedQtyCWQtyForItem(InventLocation::find(inventInventoryMovementJournalEntry.InventoryWarehouseId),inventInventoryMovementJournalEntry.ItemNumber, inventInventoryMovementJournalEntry.CatchWeightQuantity);

                inventJournalTrans.PdsCWQty = inventInventoryMovementJournalEntry.CatchWeightQuantity;
                inventJournalTrans.modifiedField(fieldNum(InventJournalTrans, PdsCWQty));
            }
            else
            {

                inventInventoryMovementJournalEntry.InventoryQuantity = METJournalUnitConversion::construct().getConvertedQtyCWQtyForItem(InventLocation::find(inventInventoryMovementJournalEntry.InventoryWarehouseId),inventInventoryMovementJournalEntry.ItemNumber, inventInventoryMovementJournalEntry.InventoryQuantity);
                inventJournalTrans.Qty = inventInventoryMovementJournalEntry.InventoryQuantity;
            }
        }
    }
}
